export async function onRequest(context) {
  const { request, next, env } = context
  const url = new URL(request.url)

  // Only protect thoughts routes
  if (!url.pathname.startsWith('/thoughts') && !url.pathname.startsWith('/api/auth')) {
    return next()
  }

  // Let auth API through
  if (url.pathname === '/api/auth') {
    return next()
  }

  // No password configured → allow access
  if (!env.THOUGHTS_PASSWORD) {
    return next()
  }

  // Check cookie
  const cookieHeader = request.headers.get('Cookie') || ''
  const match = cookieHeader.match(/(?:^|;\s*)thoughts-auth=([^;]+)/)
  const cookieValue = match ? match[1] : null

  if (cookieValue) {
    const expected = await hashPassword(env.THOUGHTS_PASSWORD)
    if (cookieValue === expected) {
      return next()
    }
  }

  // Blocked
  return new Response(getLoginPage(), {
    status: 401,
    headers: { 'Content-Type': 'text/html; charset=utf-8' },
  })
}

async function hashPassword(password) {
  const encoder = new TextEncoder()
  const data = encoder.encode(password + 'thoughts-salt-2026')
  const hash = await crypto.subtle.digest('SHA-256', data)
  return btoa(String.fromCharCode(...new Uint8Array(hash)))
}

export async function onRequestPost(context) {
  const { request, env } = context

  if (!env.THOUGHTS_PASSWORD) {
    return new Response(JSON.stringify({ ok: true }), {
      headers: { 'Content-Type': 'application/json' },
    })
  }

  let body
  try { body = await request.json() } catch {
    return new Response(JSON.stringify({ error: 'bad request' }), {
      status: 400,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const { password } = body
  if (!password || password !== env.THOUGHTS_PASSWORD) {
    return new Response(JSON.stringify({ error: 'wrong password' }), {
      status: 401,
      headers: { 'Content-Type': 'application/json' },
    })
  }

  const token = await hashPassword(password)
  const cookie = [
    `thoughts-auth=${token}`,
    'Path=/thoughts',
    'HttpOnly',
    'Secure',
    'SameSite=Lax',
    'Max-Age=2592000',
  ].join('; ')

  return new Response(JSON.stringify({ ok: true }), {
    headers: {
      'Content-Type': 'application/json',
      'Set-Cookie': cookie,
    },
  })
}

